            background-size: 20px 20px;
            background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
        }

        footer {
            background-color: #333;
            color: #999;
            padding: 40px 0;
            text-align: center;
            font-size: 14px;
        }

        @media (max-width: 768px) {
            .nav-wrapper {
                flex-direction: column;
                height: auto;
                padding: 10px 0;
            }
            nav ul {
                margin-top: 15px;
                gap: 15px;
                font-size: 14px;
            }
            .hero h1 { font-size: 32px; }
            .highlight-grid { grid-template-columns: 1fr; }
            .hero { height: 400px; }
        }
    </style>
</head>
